232: void LanLinkProvider::sendUdpDiscoveryPacket(const QList<QHostAddress> &addresses)
233: {
234:     // Broadcast from every local IP address to reach all networks
235:     QUdpSocket sendSocket;
236:     sendSocket.setProxy(QNetworkProxy::NoProxy);
237:     for (const QNetworkInterface &iface : QNetworkInterface::allInterfaces()) {
238:         if ((iface.flags() & QNetworkInterface::IsUp) && (iface.flags() & QNetworkInterface::IsRunning)) {
239:             for (const QNetworkAddressEntry &ifaceAddress : iface.addressEntries()) {
240:                 QHostAddress sourceAddress = ifaceAddress.ip();
241:                 if (sourceAddress.protocol() == QAbstractSocket::IPv4Protocol && sourceAddress != QHostAddress::LocalHost) {
242:                     qCDebug(KDECONNECT_CORE) << "Broadcasting as" << sourceAddress;
243:                     sendSocket.bind(sourceAddress);
244:                     sendUdpDiscoveryPacket(sendSocket, addresses);
245:                     sendSocket.close();
246:                 }
247:             }
248:         }
249:     }
250: }
