582: template<typename Map, typename Key>
583: static bool rateLimit(Map &lastConnectionTime, qint64 &lastCleanup, const Key &key)
584: {
585:     const qint64 now = QDateTime::currentMSecsSinceEpoch();
586:     if (now - lastCleanup >= MILLIS_DELAY_BETWEEN_CONNECTIONS_TO_SAME_DEVICE) {
587:         for (auto it = lastConnectionTime.begin(); it != lastConnectionTime.end();) {
588:             if (it.value() + MILLIS_DELAY_BETWEEN_CONNECTIONS_TO_SAME_DEVICE <= now) {
589:                 it = lastConnectionTime.erase(it);
590:             } else {
591:                 ++it;
592:             }
593:         }
594:         lastCleanup = now;
595:     }
596: 
597:     const auto last = lastConnectionTime.constFind(key);
598:     if (last != lastConnectionTime.cend() && last.value() + MILLIS_DELAY_BETWEEN_CONNECTIONS_TO_SAME_DEVICE > now) {
599:         qCDebug(KDECONNECT_CORE) << "Discarding second connection from" << key << "received too quickly";
600:         return true;
601:     }
602:     if (last == lastConnectionTime.cend() && lastConnectionTime.size() >= MAX_TRACKED_CONNECTION_TIMES) {
603:         qCDebug(KDECONNECT_CORE) << "Too many recent connections, ignoring" << key;
604:         return true;
605:     }
606:     lastConnectionTime.insert(key, now);
607:     return false;
608: }
