656: void LanLinkProvider::configureSocket(QSslSocket *socket)
657: {
658:     socket->setProxy(QNetworkProxy::NoProxy);
659:     socket->setSocketOption(QAbstractSocket::KeepAliveOption, QVariant(1));
660: 
661: #if defined(TCP_KEEPIDLE) || defined(TCP_KEEPALIVE) || defined(TCP_USER_TIMEOUT)
662:     // Detect dead connections in ~60s instead of the system default (~7875s on
663:     // Linux, ~7800s on macOS). Without this, a phone that silently disappears
664:     // (e.g. WiFi off) leaves a stale connection where isReachable() remains true
665:     // and sends fail without any user-visible error (BUG 476747).
666:     int fd = socket->socketDescriptor();
667:     if (fd >= 0) {
668: #if defined(TCP_KEEPIDLE) || defined(TCP_KEEPALIVE)
669:         int idle = 30; // seconds before first keepalive probe
670:         int intvl = 10; // seconds between probes
671:         int cnt = 3; // failed probes before connection is dropped
672: #ifdef TCP_KEEPIDLE
673:         setsockopt(fd, IPPROTO_TCP, TCP_KEEPIDLE, &idle, sizeof(idle));
674: #else
675:         // Darwin has no TCP_KEEPIDLE, TCP_KEEPALIVE is its equivalent
676:         setsockopt(fd, IPPROTO_TCP, TCP_KEEPALIVE, &idle, sizeof(idle));
677: #endif
678:         setsockopt(fd, IPPROTO_TCP, TCP_KEEPINTVL, &intvl, sizeof(intvl));
679:         setsockopt(fd, IPPROTO_TCP, TCP_KEEPCNT, &cnt, sizeof(cnt));
680: #endif
681: #ifdef TCP_USER_TIMEOUT
682:         // Force unacknowledged retransmissions to abort after 60s
683:         // (matches idle + intvl * cnt), preventing 15-minute retransmit delays
684:         unsigned int userTimeout = 60000; // milliseconds
685:         setsockopt(fd, IPPROTO_TCP, TCP_USER_TIMEOUT, &userTimeout, sizeof(userTimeout));
686: #endif
687:     }
688: #endif
689: }
