73:     // FIXME: Remove packet-type-specific logic from the link
74:     if (np.type() == PACKET_TYPE_SHARE_REQUEST && np.payload()) {
75:         // A new file to share (even one with no payload, like an empty file, which still has a
76:         // payload device attached by SharePlugin::shareUrl() even though its size is 0). This
77:         // goes through the composite job so it gets counted and sequenced with the others.
78:         // Note: CompositeUploadJob strips the payload device before re-sending this packet as a
79:         // header once it's this file's turn, so that re-send falls through to the plain write
80:         // below instead of being mistaken for another new file and re-enqueued.
81:         Device *device = Daemon::instance()->getDevice(deviceId());
82:         if (device == nullptr) {
83:             qCWarning(KDECONNECT_CORE) << "Device disconnected" << deviceId();
84:             return false;
85:         }
86: 
87:         if (!m_compositeUploadJob || !m_compositeUploadJob->isRunning()) {
88:             m_compositeUploadJob = new CompositeUploadJob(device, true);
89:         }
90: 
91:         m_compositeUploadJob->addSubjob(new UploadJob(np));
92: 
93:         if (!m_compositeUploadJob->isRunning()) {
94:             m_compositeUploadJob->start();
95:         }
96: 
97:         return true;
98:     } else if (np.payload() && np.hasPayload()) { // Infinite stream
99:         Device *device = Daemon::instance()->getDevice(deviceId());
100:         if (device == nullptr) {
101:             qCWarning(KDECONNECT_CORE) << "Device disconnected" << deviceId();
102:             return false;
103:         }
104: 
105:         CompositeUploadJob *fireAndForgetJob = new CompositeUploadJob(device, false);
106:         fireAndForgetJob->addSubjob(new UploadJob(np));
107:         fireAndForgetJob->start();
108: 
109:         return true;
110:     } else {
111:         int written = m_socket->write(np.serialize());
112: 
113:         // Actually we can't detect if a packet is received or not. We keep TCP
114:         //"ESTABLISHED" connections that look legit (return true when we use them),
115:         // but that are actually broken (until keepalive detects that they are down).
116:         return (written != -1);
