28: void PairingHandler::packetReceived(const NetworkPacket &np)
29: {
30:     bool wantsPair = np.get<bool>(QStringLiteral("pair"));
31:     if (wantsPair) {
32:         switch (m_pairState) {
33:         case PairState::Requested:
34:             m_pairingTimeout.stop();
35:             pairingDone();
36:             break;
37:         case PairState::RequestedByPeer:
38:             qCDebug(KDECONNECT_CORE) << "Ignoring second pairing request before the first one timed out";
39:             break;
40:         case PairState::Paired:
41:             // Pairing requests have a timestamp, pairing accepts don't
42:             if (!np.has(QStringLiteral("timestamp"))) {
43:                 qCDebug(KDECONNECT_CORE) << "Ignoring pairing accept from a device we already trusted";
44:                 break;
45:             }
46:             m_pairState = PairState::NotPaired;
47:             Q_EMIT unpaired();
48:             [[fallthrough]]; // Treat as unpaired from here
49:         case PairState::NotPaired:
50:             m_pairingTimestamp = np.get<long>(QStringLiteral("timestamp"), -1L);
51:             if (m_pairingTimestamp == -1L) {
52:                 qCWarning(KDECONNECT_CORE) << "Ignoring pairing request without timestamp";
53:                 return;
54:             }
55:             long currentTimestamp = QDateTime::currentDateTime().toSecsSinceEpoch();
56:             if (abs(m_pairingTimestamp - currentTimestamp) > ALLOWED_TIMESTAMP_TIME_DIFFERENCE_SECONDS) {
57:                 Q_EMIT pairingFailed(i18n("Device clocks are out of sync"));
58:                 return;
59:             }
60: 
61:             m_pairState = PairState::RequestedByPeer;
62:             m_pairingTimeout.start();
63:             Q_EMIT incomingPairRequest();
64:             break;
65:         }
66:     } else { // wantsPair == false
67:         m_pairingTimeout.stop();
68:         qCDebug(KDECONNECT_CORE) << "Unpair request received";
69:         switch (m_pairState) {
70:         case PairState::NotPaired:
71:             qCDebug(KDECONNECT_CORE) << "Ignoring unpair request for already unpaired device";
72:             break;
73:         case PairState::Requested: // We started pairing and got rejected
74:         case PairState::RequestedByPeer: // They stared pairing, then cancelled
75:             m_pairState = PairState::NotPaired;
76:             Q_EMIT pairingFailed(i18n("Canceled by other peer"));
77:             break;
78:         case PairState::Paired:
79:             m_pairState = PairState::NotPaired;
80:             Q_EMIT unpaired();
